import numpy as np,pandas as pd
from scipy.optimize import minimize,brentq
from sklearn.linear_model import Ridge,Lasso
from sklearn.preprocessing import StandardScaler,PolynomialFeatures,SplineTransformer
from sklearn.model_selection import KFold
from sklearn.metrics import mean_squared_error
from catboost import CatBoostRegressor
from threadpoolctl import threadpool_limits
threadpool_limits(2)
df=pd.read_csv('alloy_pair_target_train.csv'); nums=[x for x in df.select_dtypes('number') if x not in ['target','Fe']]; cats=['heat_treatment','route']; y=df.target.to_numpy()
catcols=list(pd.get_dummies(df[cats],drop_first=True).columns)
def catmat(x):return pd.get_dummies(x[cats],drop_first=False,dtype=float).reindex(columns=catcols,fill_value=0).to_numpy()
std=StandardScaler().fit(df[nums])
class Basis:
 def __init__(self,kind):
  self.kind=kind
  if kind=='sparse':self.trans=PolynomialFeatures(2,include_bias=False).fit(std.transform(df[nums]))
  if kind=='spline':self.trans=SplineTransformer(n_knots=3,degree=3).fit(df[nums])
 def transform(self,x):
  z=std.transform(x[nums])
  if self.kind=='add': a=np.c_[z,z**2]
  if self.kind=='sparse':a=self.trans.transform(z)
  if self.kind=='spline':a=self.trans.transform(x[nums])
  return np.c_[catmat(x),a]
models=[]
for kind,alpha in [('add',.05),('sparse',.3),('sparse',.7),('spline',.5)]:
 basis=Basis(kind);a=basis.transform(df);scale=StandardScaler().fit(a);a=scale.transform(a)
 pvs=np.zeros(len(y))
 for tr,te in list(KFold(5,shuffle=True,random_state=42).split(df))+[(np.arange(len(df)),np.arange(len(df)))]:
  weights=np.ones(len(tr)); reg=Lasso(alpha=alpha,max_iter=20000) if kind=='sparse' else Ridge(alpha=alpha)
  for i in range(25):
   reg.fit(a[tr],y[tr],sample_weight=weights);res=y[tr]-reg.predict(a[tr]);weights=np.minimum(1,12/np.maximum(abs(res),1e-4))
  if len(tr)<len(y):pvs[te]=reg.predict(a[te])
 models.append((kind+str(alpha),basis,scale,reg))
 print(kind,alpha,'cv RMSE',mean_squared_error(y,pvs)**.5,flush=True)
for depth in [3,5]:
 pv=np.zeros(len(df))
 for tr,te in KFold(5,shuffle=True,random_state=42).split(df):
  reg=CatBoostRegressor(iterations=1200,depth=depth,learning_rate=.035,l2_leaf_reg=5,verbose=False,thread_count=2)
  reg.fit(df.iloc[tr][nums+cats],y[tr],cat_features=cats);pv[te]=reg.predict(df.iloc[te][nums+cats])
 print('CatBoost depth',depth,'CV RMSE',mean_squared_error(y,pv)**.5,flush=True)
anchor=df.loc[[df.target.idxmax()]].copy()
# Preserve the high-strength anchor's treatment and processing; target the change via route, Ti and Cu.
def predictions(x):
 return np.array([y[anchor.index[0]] + reg.predict(sc.transform(b.transform(x)))[0]-reg.predict(sc.transform(b.transform(anchor)))[0] for _,b,sc,reg in models])
candidate=anchor.copy();candidate['route']='wrought'
for ti,cu in [(.3,1.5),(.4,1.6),(.5,1.7),(.5,1.3),(.35,1.5)]:
 candidate['Ti']=ti; candidate['Cu']=cu;print('CANDIDATE',ti,cu,'predictions', predictions(candidate),flush=True)
# Minimize change from the observed sample subject to hitting the model-ensemble target.
def setx(v):
 x=candidate.copy();x['Ti']=v[0];x['Cu']=v[1];return x
x0=anchor[['Ti','Cu']].to_numpy()[0];s=std.scale_[[nums.index('Ti'),nums.index('Cu')]]
result=minimize(lambda v:np.sum(((v-x0)/s)**2),[.4,1.5],constraints=[{'type':'eq','fun':lambda v:predictions(setx(v)).mean()-1051}],bounds=[(.0054,1.5),(.0003,2.3514)],method='SLSQP',options={'ftol':1e-10})
opt=setx(result.x);print('OPTIMUM',result.success,result.x,predictions(opt));print(opt[nums+cats].to_string(index=False));print('ALLOY SUM',opt[nums[:12]].sum(axis=1).iloc[0])
import joblib
joblib.dump({'models':models,'recipe':opt,'anchor':anchor,'std':std,'nums':nums,'catcols':catcols},'recipe_search.joblib')

